const sd = $getWorkflowStaticData('global');
const reg = sd.faturamento_registrados || [];
const novos = $input.all().map(i => i.json).filter(h => h && h.id && !reg.includes(h.id));
if (novos.length === 0) return [];
const ids = [...new Set(novos.map(h => h.pedido_id))].join(',');
return [{ json: { historico: novos, ids } }];

const brl = n => 'R$ ' + Number(n).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const pad = n => String(n).padStart(2, '0');
const brt = d => new Date(new Date(d).getTime() - 3 * 3600 * 1000); // America/Sao_Paulo (UTC-3, sem horario de verao)
const dataBR = d => { const x = brt(d); return pad(x.getUTCDate()) + '/' + pad(x.getUTCMonth() + 1) + '/' + x.getUTCFullYear(); };
const horaBR = d => { const x = brt(d); return pad(x.getUTCHours()) + ':' + pad(x.getUTCMinutes()); };

const hist = $('Filtrar nao registrados').first().json.historico;
const pedidos = Object.fromEntries($input.all().map(i => [i.json.id, i.json]));
return hist.filter(h => pedidos[h.pedido_id]).map(h => {
  const p = pedidos[h.pedido_id];
  const d = brt(h.created_at);
  const iso = d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
  return { json: {
    historico_id: h.id,
    payload: {
      evento: 'faturamento_registrado',
      data_conclusao: iso,
      hora_conclusao: horaBR(h.created_at),
      pedido_numero: p.numero,
      cliente_nome: p.cliente_nome,
      valor_total: Number(p.valor_total),
      valor_total_formatado: brl(p.valor_total),
      forma_pagamento: p.forma_pagamento || 'não informado'
    }
  }};
});

const sd = $getWorkflowStaticData('global');
const ids = $input.all().map(i => i.json.historico_id);
sd.faturamento_registrados = [...(sd.faturamento_registrados || []), ...ids].slice(-500);
return [{ json: { registrados_agora: ids.length, total_em_memoria: sd.faturamento_registrados.length } }];
